  delta=R-r*z[k];D=gap+mp.sqrt(gap*gap+abs(delta)**2);K=mul(K,[delta/D,1])
 A=mul(C,H);B=mul(C,K)
 for j in range(a):A=mul(A,[x,1]);B=mul(B,[y,1])
